// components/pages/LineRegistration.js
import React, { useState } from 'react';
import { apiCall } from '../../utils/api';

const LineRegistration = ({ showToast }) => {
  const [formData, setFormData] = useState({
    name: '',
    idNumber: '',
    phone: '',
    dob: ''
  });
  const [loading, setLoading] = useState(false);
  const [feedback, setFeedback] = useState('');

  const handleChange = (e) => {
    setFormData({
      ...formData,
      [e.target.name]: e.target.value
    });
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    const { name, idNumber, phone, dob } = formData;
    
    if (!name || !idNumber || !phone || !dob) {
      setFeedback({ type: 'error', message: 'All fields are required' });
      return;
    }

    setLoading(true);
    setFeedback({ type: 'info', message: 'Registering...' });

    const cleanPhone = phone.replace(/\D/g, '');
    const res = await apiCall('registerLine', { 
      name, 
      idNumber, 
      phone: cleanPhone, 
      dob 
    });

    if (res.success) {
      setFeedback({ type: 'success', message: 'Line registered successfully!' });
      setFormData({ name: '', idNumber: '', phone: '', dob: '' });
      showToast('Line registered successfully!');
      setTimeout(() => setFeedback(''), 3000);
    } else {
      setFeedback({ type: 'error', message: res.error });
    }
    setLoading(false);
  };

  return (
    <div className="form-container">
      <h3 className="section-title"><i className="fas fa-user-plus"></i> Register New Line</h3>
      <form className="vertical-form" onSubmit={handleSubmit}>
        <div className="form-group">
          <label><i className="fas fa-user"></i> Full Name</label>
          <input 
            type="text" 
            name="name"
            value={formData.name}
            onChange={handleChange}
            placeholder="Enter full name"
          />
        </div>
        <div className="form-group">
          <label><i className="fas fa-id-card"></i> ID Number</label>
          <input 
            type="text" 
            name="idNumber"
            value={formData.idNumber}
            onChange={handleChange}
            placeholder="Enter ID number"
          />
        </div>
        <div className="form-group">
          <label><i className="fas fa-phone"></i> Phone Number</label>
          <input 
            type="tel" 
            name="phone"
            value={formData.phone}
            onChange={handleChange}
            placeholder="0712345678"
          />
        </div>
        <div className="form-group">
          <label><i className="fas fa-calendar"></i> Date of Birth</label>
          <input 
            type="date" 
            name="dob"
            value={formData.dob}
            onChange={handleChange}
          />
        </div>
        <button type="submit" className="btn" disabled={loading}>
          <i className="fas fa-save"></i> {loading ? 'Registering...' : 'Register Line'}
        </button>
        {feedback && (
          <div className={`fetch-info ${feedback.type}`} style={{ marginTop: '1rem' }}>
            {feedback.message}
          </div>
        )}
      </form>
    </div>
  );
};

export default LineRegistration;
